// inflection::Inflector::underscore(const std::string& in) -> std::string
// Operates on raw BYTES. No allocation limit, no truncation, no state.
// Pure: identical input always yields identical output; independent of
// initialize(), of argv position, and of any pluralization/irregular-word rules.

string underscore(string in):
    string out = ""                       // starts empty
    for i = 0 .. in.size()-1:             // i is the BYTE INDEX into the INPUT
        byte c = in[i]
        if (c >= 0x41 && c <= 0x5A):      // 'A'..'Z' ONLY (ASCII uppercase, "C" locale)
            if (i > 0):                   // <-- condition is on the INPUT INDEX, not on out.empty()
                out += '_'                // 0x5F
            out += (byte)(c + 0x20)       // tolower: 'A'->'a' ... 'Z'->'z'
        else:
            out += c                      // every other byte copied verbatim, unchanged
    return out

// Equivalent one-liner: for each byte, an ASCII A-Z becomes "_" + lowercase,
// except at byte index 0 where the leading "_" is omitted. Nothing else changes.
//
// NOT done by this function (all explicitly disproven):
//   - no collapsing / de-duplication of adjacent or pre-existing '_' bytes
//   - no acronym grouping (HTMLParser -> h_t_m_l_parser, one '_' per capital)
//   - no "::" -> "/" translation (Rails-style) ; "::" is passed through as-is
//   - no '-' -> '_' translation ; no whitespace -> '_' translation
//   - no trimming, no leading/trailing '_' cleanup
//   - no digit/word-boundary insertion ("Test99" -> "test99", "99Test" -> "99_test"
//     only because 'T' is uppercase)
//   - no UTF-8 awareness; multi-byte sequences are copied byte-for-byte and each
//     of their bytes still consumes an index (so a capital after them gets a '_')

// Driver / CLI behavior of /workspace/dataset/test15_executable
// All output on STDOUT (fd 1). Nothing is ever written to stderr except the
// uncaught-exception abort message described below. argv[0] is never used.
// stdin is never read. No flag/option parsing whatsoever: "-h", "--help",
// "--", "-" are treated as ordinary words.

main(argc, argv):
    Inflector::initialize()          // produces NO output
    results = []                     // std::vector<std::string>, buffered

    // NOTE: loop guard is `i < argc && i <= 5`, so at most args 1..5 are used.
    N = min(argc - 1, 5)             // number of processed args
    for i in 1 .. N:                 // 1-based index into argv
        word = argv[i]               // raw bytes, no copy/trim/decoding
        results.push_back(pluralize(word))
        results.push_back(camelize(word))
        if i % 2 == 0:               // i.e. only i == 2 and i == 4
            results.push_back(underscore(word))

    for r in results:                // ALL buffered results printed FIRST
        write(stdout, r); write(stdout, "\n")   // std::endl => '\n' + flush

    if argc > 1:                     // trailing 3 lines, only if >=1 arg given
        write(stdout, isPlural(argv[1])   ? "1" : "0"); write "\n"
        write(stdout, isSingular(argv[1]) ? "1" : "0"); write "\n"
        // no std::boolalpha => bools print as the bytes '0' / '1'
        write(stdout, demodulize("Module::" + argv[1])); write "\n"
    return 0

// ---------------- LINE LAYOUT ----------------
// Let N = min(argc-1, 5).
// TOTAL_LINES = 0                                      if N == 0
//             = 2*N + floor(N/2) + 3                   if N >= 1
//   N: 0 1 2 3  4  5 (and 5 for every argc-1 >= 5)
//   L: 0 5 8 10 13 15
//
// Line order (1-based), for N >= 1:
//   block(i) for i = 1..N, concatenated in order:
//        pluralize(argv[i])
//        camelize(argv[i])
//        underscore(argv[i])        // present ONLY when i is even (i==2, i==4)
//   then exactly 3 trailing lines:
//        isPlural(argv[1])   as '0'/'1'
//        isSingular(argv[1]) as '0'/'1'
//        demodulize("Module::" + argv[1])
//
// Concrete absolute line indices:
//   N=1: 1 plur(a1) 2 cam(a1) | 3 isPlural 4 isSingular 5 demodulize
//   N=2: 1 plur(a1) 2 cam(a1) 3 plur(a2) 4 cam(a2) 5 und(a2) | 6,7,8
//   N=3: ... 6 plur(a3) 7 cam(a3) | 8,9,10
//   N=4: ... 8 plur(a4) 9 cam(a4) 10 und(a4) | 11,12,13
//   N=5: ... 11 plur(a5) 12 cam(a5) | 13,14,15
// Args 6, 7, 8, ... 200 are read from argv but completely ignored.

// ---------------- BYTES / NEWLINES ----------------
// Every emitted line is terminated by exactly one 0x0A. There is a trailing
// newline after the final line. With 0 args the output is 0 bytes (no newline).
// Embedded '\n' / '\t' / ' ' inside an argument are passed through verbatim and
// therefore split what looks like one "line" into several physical lines.

// ---------------- EXIT CODES ----------------
// exit 0 in every normal case (including 0 args, empty args in positions >= 2).
// CRASH (uncaught std::out_of_range from demodulize's substr) iff:
//        argv[1] == ""  OR  argv[1] ends with the byte ':'
//   (because s = "Module::"+argv[1]; pos = s.rfind(':'); s.substr(pos+2)
//    and pos+2 > s.size() exactly when the last ':' is the final byte)
//   -> std::terminate -> SIGABRT (signal 6), shell-observed exit status 134,
//      core dumped. All previously produced lines (the whole results vector
//      PLUS the isPlural and isSingular lines) are already flushed to stdout
//      before the abort, because std::endl flushes each line.
//   stderr on crash, byte-exact (147 bytes, two lines):
//     "terminate called after throwing an instance of 'std::out_of_range'\n"
//     "  what():  basic_string::substr: __pos (which is P) > this->size() (which is S)\n"
//   where S = 8 + len(argv[1]) and P = S + 1.
//   (Note the two spaces after "what():" and after the colon.)

// ---------------- LOCALE ----------------
// Output is byte-identical under LC_ALL = C, POSIX, C.UTF-8, en_US.UTF-8,
// de_DE.UTF-8, tr_TR.UTF-8. No locale is ever imbue'd; case mapping is plain
// ASCII (Turkish 'I'/'i' behave exactly as in C). Non-ASCII UTF-8 bytes
// (>= 0x80) and invalid UTF-8 (e.g. 0xFF 0xFE) pass through untouched, so all
// string handling is byte-wise, not codepoint-wise.

// inflection::Inflector::camelize(const std::string& input) -> std::string
// Pure byte-level transform. Stateless (no dependence on Inflector::initialize()
// tables, no memoization, no dependence on other args). Never throws, never
// truncates, no length limit. Operates on raw bytes of std::string.
//
// The ONLY separator byte is '_' (0x5F). No other byte (including '-', ' ',
// '.', '/', ':', ';', ',', '\t', '\n', '\r', '\v', '\f', digits, 0x7F,
// and every byte 0x80..0xFF) is a separator or is otherwise special.
// Uppercasing is ASCII-only ("C" locale std::toupper): exactly 'a'..'z'
// (0x61..0x7A) map to 'A'..'Z' (0x41..0x5A); every other byte is emitted
// unchanged.
// The capitalize flag is cleared by ANY non-'_' byte, even one that cannot be
// uppercased ("a_-b" -> "a-b", NOT "a-B").
// The first byte of the result is NEVER forced to upper or lower case unless it
// was preceded by at least one '_' in the input.

function camelize(input):
    out = ""                       // empty std::string
    cap = false
    for each byte c in input:      // left to right, no lookahead
        if c == 0x5F ('_'):
            cap = true             // separator is consumed, never emitted
        else if cap:
            if 0x61 <= c <= 0x7A:  // 'a'..'z'
                out += (c - 0x20)  // ASCII uppercase
            else:
                out += c           // unchanged (digits, symbols, 'A'-'Z',
                                   //  control bytes, 0x80..0xFF)
            cap = false
        else:
            out += c
    return out
    // note: a trailing run of '_' leaves cap == true at end-of-string and
    // contributes nothing to the output; an all-'_' input returns "".

// Equivalent formulation (behaviorally indistinguishable in every probe):
//   split input on '_' into tokens (keeping empty tokens);
//   result = token[0] + concat over i>=1 of ascii_upcase_first_byte(token[i])
//   where ascii_upcase_first_byte("") == "".

// inflection::Inflector::demodulize(const std::string& s)  -- BYTE-level spec
// CONFIRMED implementation is exactly:
//     size_t pos = s.rfind(':');          // last occurrence of the single BYTE 0x3A
//     return s.substr(pos + 2);           // throws std::out_of_range if pos+2 > s.size()
//
// Note the off-by-one: the intent was rfind("::") + 2 (== skip the two colons);
// the code searches for ONE colon but skips TWO bytes past it, so it always
// eats the last colon AND the byte immediately after it.

function demodulize(s: bytes) -> bytes:
    # 1. find index of the LAST byte equal to 0x3A (':')
    pos = -1
    for i in 0 .. len(s)-1:
        if s[i] == 0x3A: pos = i          # plain unsigned-byte equality; 0xBA etc. do NOT match
    # 2. no colon at all  -> std::string::rfind returns npos == SIZE_MAX (2^64-1);
    #    npos + 2 wraps to 1 (unsigned overflow), so the C++ code would evaluate s.substr(1).
    #    (Cannot be exercised through this driver: the driver always prepends "Module::".)
    if pos == -1:
        start = 1                          # inferred from unsigned wraparound, NOT observed
    else:
        start = pos + 2
    # 3. bounds check exactly like std::string::substr
    if start > len(s):
        THROW std::out_of_range(
          "basic_string::substr: __pos (which is " + start + ") > this->size() (which is " + len(s) + ")")
        # uncaught -> std::terminate -> abort (SIGABRT), process exit status 134 via shell
    # 4. byte slice to end of string, NO other transformation:
    #    no case change, no trimming, no UTF-8 awareness, no separator normalisation
    return s[start .. len(s)-1]            # empty string when start == len(s)

// Equivalent phrasing: take everything after the last ':' byte, then drop its first byte;
// error if there is nothing after the last ':' (i.e. the string's last byte is ':').

// ===== Specialised to this driver, where input = "Module::" + W =====
// len = 8 + len(W). "Module::" always supplies a ':' at index 7, so pos != -1 always.
//   if W is empty or W's LAST byte is ':'  -> last colon is at index len-1 -> start = len+1 > len -> CRASH
//   else if W contains ':' :
//        k = index (within W) of W's last ':' byte
//        result = W[k+2 ..]      (empty when k == len(W)-2)
//   else (no ':' in W):
//        pos = 7 (the second colon of "Module::"), start = 9 -> result = W[1..]  (W minus its FIRST BYTE)

// PORTING NOTE (Rust): must slice BYTES, e.g. &s.as_bytes()[start..], and produce a
// Vec<u8>/String::from_utf8_lossy-free byte string, because the result is frequently
// INVALID UTF-8 (see goldens for "é" and "日本語"). Using char_indices / &str[..] would panic.

// inflection::Inflector::pluralize(const std::string& word) -> std::string
// Pure byte-level operation. No locale/case/UTF-8 awareness whatsoever.

CONST UNCOUNTABLE : set of exact byte strings = {
    "equipment",
    "information",
    "rice",
    "money",
    "species",
    "series",
    "fish",
    "sheep",
    "jeans",
    "police"
}   // exactly 10 entries == Rails' default `uncountables` list, all lowercase ASCII

function pluralize(word):
    if word.size() == 0:
        return ""                      // identity on empty input (NOT "s")
    if UNCOUNTABLE.contains(word):     // EXACT, byte-for-byte, case-SENSITIVE,
        return word                    // whole-string equality. No trimming,
                                       // no lowercasing, no substring or
                                       // word-boundary scan, no suffix stripping.
    return word + "s"                  // append the single byte 0x73 ('s')

// Equivalent one-liner:
//   result = (word.empty() || UNCOUNTABLE.count(word)) ? word : word + 's';
//
// NON-BEHAVIORS (all explicitly verified):
//  * There are NO other rules at all. No -es for s/ss/sh/ch/x/z endings,
//    no y->ies, no f/fe->ves, no o->oes, no is->es, no us->i, no um->a,
//    no on->a, no ix/ex->ices, and NO irregular table (man/woman/child/
//    person/tooth/foot/goose/mouse/louse/ox/die/penny/quiz/datum/index/
//    matrix/appendix/criterion/...). Every one gains a trailing 's'.
//  * Uncountables NOT in the set despite being plausible: news, water, data,
//    staff, advice, music, luggage, furniture, bison, salmon, trout, swine,
//    aircraft, offspring, deer, moose, buffalo, corps, means, scissors,
//    pants, shoes, clothes, glasses, chinese, japanese, mathematics, physics,
//    software, homework, research, evidence, feedback, traffic, weather,
//    cattle, people, gold, milk, cash, ... (263 candidates swept; only the
//    10 listed above were unchanged).
//  * Bytes are never inspected or transformed other than the append. Any byte
//    0x01..0xFF in any position (incl. invalid UTF-8 such as 0xFF, 0x80,
//    0xC0 0xAF) passes through unchanged with 0x73 appended.
//  * Length is unbounded (verified 100000-byte input -> 100001 bytes).
//  * Never throws; exit code 0; nothing on stderr.
//    (The only crash in this binary comes from demodulize("Module::") when
//     argv[1] is empty -- pluralize itself already produced "" successfully.)
